SourceCode.Declaration:
public class TFMDocumentTypeAttribute extends SysAttribute implements SysExtensionIAttribute
{

    TFMDocumentTypeId           documentType;
    TFMDocumentContentSubject   contentType;
    MethodName                  methodName;

}

Method.Source:
void new(TFMDocumentTypeId _documentType, TFMDocumentContentSubject _contentType = '', MethodName _methodName = '')
{
    super();

    contentType = _contentType;

    documentType = _documentType;
    if (documentType == classStr(TFMGetRegistrationConfiguration) || documentType == classStr(TFMPostAdhocRegistration) || documentType == classStr(TFMLookup))
    {
        documentType = subStr(documentType,4,100);
    }
    methodName = _methodName;
}

public TFMDocumentContentSubject parmContentType(TFMDocumentContentSubject _contentType = contentType)
{
    contentType = _contentType;

    return contentType;
}

public TFMDocumentTypeId parmDocumentType(TFMDocumentTypeId _documentType = documentType)
{
    documentType = _documentType;

    return documentType;
}
